<h2 class="wp-block-wdl-custom-title-2 custom-title-2 center"><span class="main"><span data-lw_font_set="Shippori Mincho" class="custom-font-settings custom-font-settings fs-0-8">ハーブピーリングとは</span></span><span class="sub">削って剥くのではなく、肌が自分で生まれ変わる力を借りる施術です。</span></h2>
<!-- /wp:wdl/custom-title-2 -->

<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":12,"spHeight":8} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:12px"></div><div class="sp" style="height:8px"></div></div>
