<!-- wp:wdl/lw-content-8 {"titleBorderSize":0,"liBorderColor":"#a9884b","liBorderSize":1,"liBorderRadius":0,"subBorderColor":"#a9884b","subFontColor":"#a9884b","fontLiMain":"Shippori Mincho","fontWeightLiMain":"500","showButton":false} -->
<div class="wp-block-wdl-lw-content-8 lw-content-8"><ul class="lw-content-8__inner clm_3" style="max-width:1200px;margin:0 auto"><li class="lw-content-8__li" style="border-color:#a9884b;border-width:1px;border-style:solid;padding-top:24px;padding-bottom:24px;padding-left:24px;padding-right:24px;border-radius:0px"><a href="#price" class="link"><h3 class="ttl font_size_m" data-lw_font_set="" style="font-weight:600;color:;border-bottom-color:var(--color-main);border-bottom-width:0;border-bottom-style:none"><span class="sub" data-lw_font_set="" style="font-weight:600;border-color:#a9884b;border-width:1px;border-style:solid;display:inline-block;color:#a9884b;background-color:#ffffff">step 1</span><span class="main left" data-lw_font_set="Shippori Mincho" style="font-weight:500">ハーブを肌に入れる</span></h3><p class="lw-content-8__text font_size_m" data-lw_font_set="" style="font-weight:400;color:var(--color-black)">天然のハーブを粉のまま肌に入れていきます。薬剤で表面を溶かす施術ではないので、削られる感覚はありません。ちくちくとした熱を感じる方が多いです。</p></a></li><li class="lw-content-8__li" style="border-color:#a9884b;border-width:1px;border-style:solid;padding-top:24px;padding-bottom:24px;padding-left:24px;padding-right:24px;border-radius:0px"><a href="#price" class="link"><h3 class="ttl font_size_m" data-lw_font_set="" style="font-weight:600;color:;border-bottom-color:var(--color-main);border-bottom-width:0;border-bottom-style:none"><span class="sub" data-lw_font_set="" style="font-weight:600;border-color:#a9884b;border-width:1px;border-style:solid;display:inline-block;color:#a9884b;background-color:#ffffff">step 2</span><span class="main left" data-lw_font_set="Shippori Mincho" style="font-weight:500">肌が自分で入れ替わる</span></h3><p class="lw-content-8__text font_size_m" data-lw_font_set="" style="font-weight:400;color:var(--color-black)">肌は本来28日かけて生まれ変わりますが、年齢とともに遅くなります。ハーブが刺激になって、その周期が動き出します。剥くのではなく、下から押し上げられて剥けます。</p></a></li><li class="lw-content-8__li" style="border-color:#a9884b;border-width:1px;border-style:solid;padding-top:24px;padding-bottom:24px;padding-left:24px;padding-right:24px;border-radius:0px"><a href="#price" class="link"><h3 class="ttl font_size_m" data-lw_font_set="" style="font-weight:600;color:;border-bottom-color:var(--color-main);border-bottom-width:0;border-bottom-style:none"><span class="sub" data-lw_font_set="" style="font-weight:600;border-color:#a9884b;border-width:1px;border-style:solid;display:inline-block;color:#a9884b;background-color:#ffffff">step 3</span><span class="main left" data-lw_font_set="Shippori Mincho" style="font-weight:500">5日目に落ち着く</span></h3><p class="lw-content-8__text font_size_m" data-lw_font_set="" style="font-weight:400;color:var(--color-black)">3日目から4日目に薄く粉をふき、5日目には落ち着きます。シミが薄くなった、毛穴が浅くなったと感じるのはこのタイミングです。</p></a></li></ul></div>
<!-- /wp:wdl/lw-content-8 -->

